const state={
  boot:null,view:'home',collection:null,returnView:'learn',collectionTab:'list',translation:true,
  listAudioIndex:-1,listAuto:false,listAutoDelay:1,listAutoTimer:null,listSpeed:1,audioMode:null,posTimer:null,posHandler:null,
  shadow:{running:false,index:0,repeatDone:0,timer:null,autoNext:true,speed:1,repeat:3,pause:2},
  recallMode:'vi_en',recall:null,manager:null,searchTimer:null,searchFilter:'all',searchResults:[],bulkImport:null,pendingRestoreFile:null,modalReturnFocus:null
};
const el=id=>document.getElementById(id), content=()=>el('content'), player=()=>el('player');
function esc(s=''){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function toast(t){const x=el('toast');x.textContent=t;x.classList.add('show');clearTimeout(x._t);x._t=setTimeout(()=>x.classList.remove('show'),3500)}
async function api(url,opt){const r=await fetch(url,opt);let d;try{d=await r.json()}catch{d={error:await r.text()}}if(!r.ok)throw new Error(d.error||'Có lỗi xảy ra');return d}
const post=(url,data)=>api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function setHead(t,s=''){el('pageTitle').textContent=t;el('pageSub').textContent=s}
function setNav(v){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v))}
function updateDueBadge(){const n=state.boot?.stats?.dueToday||0;el('dueBadge').textContent=n?String(n):''}
function formatNum(n){return Number(n||0).toLocaleString('vi-VN')}
function stopAllAudio(){stopShadow(false);clearTimeout(state.listAutoTimer);state.listAutoTimer=null;const p=player();p.pause();state.audioMode=null;hidePlayer()}
function clearPositionTracker(){if(state.posHandler){window.removeEventListener('scroll',state.posHandler);state.posHandler=null}clearTimeout(state.posTimer)}
async function refreshBoot(){state.boot=await api('/api/bootstrap');state.recallMode=state.boot.settings.recall_mode||state.recallMode;state.listAutoDelay=Number(state.boot.settings.list_auto_delay??1);state.shadow.speed=Number(state.boot.settings.shadow_speed||1);state.shadow.repeat=Number(state.boot.settings.shadow_repeat||3);state.shadow.pause=Number(state.boot.settings.shadow_pause||2);updateDueBadge()}
async function bootstrap(){await refreshBoot();render('home');const result=state.boot.restoreResult;if(result){post('/api/data/restore-result/ack',{}).catch(()=>{});if(result.ok){toast('Khôi phục dữ liệu thành công.')}else{openModal(`<h2>Không thể khôi phục dữ liệu</h2><p class="modal-copy">${esc(result.message||'Dữ liệu cũ đã được giữ nguyên.')}</p>${result.error?`<div class="guide-callout">${esc(result.error)}</div>`:''}<div class="form-actions"><button class="btn secondary" onclick="closeModal()">Đóng</button></div>`)}}}
function render(v){clearPositionTracker();if(!['collection','manager','recall'].includes(v))stopAllAudio();state.view=v;setNav(v);if(v==='home')home();else if(v==='learn')learn();else if(v==='vocabulary')vocabulary();else if(v==='courses')coursesView();else if(v==='review')reviewOverview();else if(v==='my')myIslandsView();else if(v==='saved')savedView();else if(v==='search')searchView();else if(v==='guide')guideView();else if(v==='settings')settingsView()}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>render(b.dataset.view));

function collectionProgress(c){const p=state.boot.collectionProgress?.[`core:${c.id}`];if(!p)return '';const pos=Math.min((p.last_index||0)+1,c.sentence_count||0);return `<span class="progress-chip">vị trí ${pos}/${c.sentence_count||0}</span>`}
function collectionRow(c,n,returnView){return `<div class="collection-row" onclick="openCollection('core',${c.id},'${returnView}',false)"><div class="collection-num">${String(n).padStart(2,'0')}</div><div class="collection-main"><b>${esc(c.name)}</b><p>${esc(c.description||c.topic_name||'')}</p></div><div class="collection-meta">${collectionProgress(c)}<span class="count-chip">${c.sentence_count||0} câu</span></div></div>`}
function dailySourceControl(source){return `<div class="daily-source"><span>Nguồn câu mới</span><b>${source?esc(source.name):'Chưa chọn bộ học'}</b><button class="daily-source-change" onclick="openDailySourcePicker()">Đổi bộ</button></div>`}
function sourcePickerRow(item){return `<button class="source-picker-row" onclick="chooseDailySource('${item.collectionKey}')"><span><b>${esc(item.name)}</b><small>${esc(item.topic_name||item.description||'')}</small></span><em>${formatNum(item.sentence_count||0)} câu</em></button>`}
function openDailySourcePicker(){const boot=state.boot,core=(boot.collections||[]).filter(x=>!x.is_vocabulary&&!String(x.source_group||'').startsWith('course:')).map(x=>({...x,collectionKey:`core:${x.id}`})),vocabulary=(boot.collections||[]).filter(x=>x.is_vocabulary).map(x=>({...x,collectionKey:`core:${x.id}`})),courses=(boot.courses||[]).flatMap(x=>(x.collections||[]).map(c=>({...c,topic_name:x.name,collectionKey:`core:${c.id}`}))),mine=(boot.myIslands||[]).map(x=>({...x,topic_name:'My Islands',collectionKey:`my:${x.id}`})),groups=[['Learn',core],['Vocabulary',vocabulary],['Courses',courses],['My Islands',mine]];openModal(`<h2>Đổi nguồn câu mới</h2><p class="modal-copy">Chọn một bộ hoặc Unit. Tiến độ và lịch FSRS hiện tại được giữ nguyên.</p><div class="source-picker">${groups.map(([name,items])=>`<details ${name==='Learn'?'open':''}><summary><b>${name}</b><span>${formatNum(items.length)} bộ</span></summary><div>${items.length?items.map(sourcePickerRow).join(''):`<p class="empty-inline">Chưa có nội dung.</p>`}</div></details>`).join('')}</div><div class="form-actions"><button class="btn ghost" onclick="closeModal()">Đóng</button></div>`)}
async function chooseDailySource(collectionKey){try{await post('/api/active-source',{collection_key:collectionKey});await refreshBoot();closeModal();if(state.view==='review')reviewOverview();else home();toast('Đã đổi nguồn câu mới; tiến độ cũ được giữ nguyên')}catch(e){toast(e.message)}}
function home(){const b=state.boot,s=b.stats,a=b.activeSource,recent=b.recent||[];setHead('Home','Học theo trình tự · luyện chủ động · ôn đúng lúc.');content().innerHTML=`
<div class="hero"><div><h2>Học hôm nay</h2><p>FSRS ưu tiên câu đến hạn, sau đó đưa câu mới từ Island đang học.</p><div class="hero-actions"><button class="btn secondary" onclick="startDaily()">Bắt đầu Daily Study</button><button class="btn" style="background:rgba(255,255,255,.14);color:#fff" onclick="render('learn')">Học tự do</button></div></div><div class="daily-box"><div class="daily-numbers"><div><strong>${s.dueToday}</strong><small>Ôn đến hạn</small></div><div><strong>${s.newToday}</strong><small>Câu mới</small></div></div>${dailySourceControl(a)}</div></div>
<div class="stats"><div class="stat"><div class="num">${formatNum(s.totalSentences)}</div><div class="label">Tổng câu trong thư viện</div></div><div class="stat"><div class="num">${s.startedSrs}</div><div class="label">Đã vào SRS</div></div><div class="stat"><div class="num">${s.reviewedToday}</div><div class="label">Lượt recall hôm nay</div></div><div class="stat"><div class="num">${s.saved}</div><div class="label">Câu đã lưu</div></div></div>
<div class="section-head"><div><h2>Tiếp tục học</h2><p>Quay lại đúng Island và vị trí gần nhất.</p></div></div>
${recent.length?`<div class="collection-list">${recent.slice(0,4).map((r,i)=>`<div class="collection-row" onclick="openCollection('${r.kind}',${r.id},'home',true)"><div class="collection-num">${i+1}</div><div class="collection-main"><b>${esc(r.name)}</b><p>${esc(r.topic_name||r.description||'')}</p></div><div class="collection-meta"><span class="progress-chip">tiếp tục #${(r.last_index||0)+1}</span><span class="count-chip">${r.sentence_count||0} câu</span></div></div>`).join('')}</div>`:`<div class="empty">Chưa có vị trí học gần đây. Mở Learn, Vocabulary hoặc Courses để bắt đầu.</div>`}
<div class="section-head"><div><h2>Quy trình khuyến nghị</h2></div><button class="link-btn" onclick="render('guide')">Xem hướng dẫn →</button></div><div class="info-strip"><div class="flow"><span>1. Learn</span><i>→</i><span>2. Shadowing</span><i>→</i><span>3. Active Recall</span><i>→</i><span>4. FSRS Review</span></div></div>`}

function learn(){setHead('Learn','8 Topics → 54 Islands · giữ đúng thứ tự nguồn.');const b=state.boot;let html='';for(const t of b.topics){const cols=b.collections.filter(c=>!c.is_vocabulary&&Number(c.topic_id)===Number(t.id));html+=`<div class="topic-block"><div class="topic-title"><h2>${esc(t.name)}</h2><small>${cols.length} Islands</small></div><div class="collection-list">${cols.map((c,i)=>collectionRow(c,i+1,'learn')).join('')}</div></div>`}content().innerHTML=html}
function vocabulary(){
  setHead('Vocabulary','Tách theo CEFR để học có trình tự: A1 → A2 → B1 → B2 → C1.');
  const cols=state.boot.collections.filter(c=>c.is_vocabulary);
  const groups=[
    ['A1',c=>/^A1\b/i.test(c.name)],
    ['A2',c=>/^A2\b/i.test(c.name)],
    ['B1',c=>/^B1\b/i.test(c.name)],
    ['B2',c=>/^B2\b/i.test(c.name)],
    ['C1',c=>/^C1\b/i.test(c.name)],
    ['Khác',c=>!(/^(A1|A2|B1|B2|C1)\b/i.test(c.name))],
  ];
  let html='';
  for(const [label,test] of groups){
    const xs=cols.filter(test).sort((a,b)=>{
      const pa=Number((a.name.match(/Part\s+(\d+)/i)||[])[1]||0),pb=Number((b.name.match(/Part\s+(\d+)/i)||[])[1]||0);
      return pa-pb || a.name.localeCompare(b.name);
    });
    if(!xs.length)continue;
    const total=xs.reduce((n,c)=>n+Number(c.sentence_count||0),0);
    html+=`<div class="topic-block vocab-group"><div class="topic-title"><h2>${label}</h2><small>${xs.length} bộ · ${formatNum(total)} câu</small></div><div class="collection-list">${xs.map((c,i)=>collectionRow(c,i+1,'vocabulary')).join('')}</div></div>`;
  }
  content().innerHTML=html;
}

function coursesView(){
  const courses=state.boot.courses||[];setHead('Courses','Chọn một Course để xem Books hoặc Units.');
  content().innerHTML=courses.length?`<div class="course-grid">${courses.map(courseCard).join('')}</div>`:'<div class="empty">Chưa có Course.</div>';
}
function courseCard(course){const unitCount=(course.collections||[]).length;return `<button class="course-card" onclick="openCourse('${esc(course.key)}')"><div><span class="course-kicker">Course</span><h2>${esc(course.name)}</h2><p>${esc(course.description||'')}</p></div><div class="course-card-meta"><span>${formatNum(unitCount)} ${course.layout==='collection'?'bộ':'Units'}</span><span>${formatNum(course.sentence_count)} câu</span><span>${course.audio_missing?`Thiếu ${formatNum(course.audio_missing)} audio`:`${formatNum(course.audio_available)} audio`}</span></div><b class="course-open">Mở Course →</b></button>`}
function openCourse(key){const course=(state.boot.courses||[]).find(x=>x.key===key);if(!course)return toast('Không tìm thấy Course');setHead(course.name,course.description||'Books / Units');let body='';if(course.layout==='collection'){body=`<div class="collection-list">${(course.collections||[]).map((c,i)=>collectionRow(c,i+1,'courses')).join('')}</div>`}else{body=(course.sections||[]).map((section,index)=>`<details class="course-book" ${index===0?'open':''}><summary><b>${esc(section.name)}</b><div class="book-summary-actions"><span>${formatNum((section.collections||[]).length)} Units · ${formatNum(section.sentence_count)} câu</span>${section.group_key?`<button class="btn ghost small" onclick="event.preventDefault();event.stopPropagation();openGroupSrsMenu('${esc(section.group_key)}','${esc(course.name+' · '+section.name)}')">Ôn tập</button>`:''}</div></summary><div class="collection-list">${(section.collections||[]).map((c,i)=>collectionRow(c,i+1,'courses')).join('')}</div></details>`).join('')}content().innerHTML=`<div class="section-head course-detail-head"><button class="btn ghost small" onclick="coursesView()">← Tất cả Courses</button><div class="section-actions"><span class="count-chip">${course.audio_missing?'Thiếu '+formatNum(course.audio_missing)+' audio':'Audio đầy đủ'}</span>${course.group_key?`<button class="btn ghost small" onclick="openGroupSrsMenu('${esc(course.group_key)}','${esc(course.name)}')">↻ Ôn tập Course</button>`:''}${course.audio_import&&course.audio_missing?`<button class="btn secondary small" onclick="beginBulkAudio('course','${esc(course.key)}','zip')">Import audio ZIP</button>`:''}</div></div>${body}`}

async function openCollection(kind,id,returnView='learn',resume=false,targetKey=null){stopAllAudio();clearPositionTracker();state.returnView=returnView;const d=await api(`/api/collection?kind=${encodeURIComponent(kind)}&id=${id}`);state.collection=d;state.collectionTab='list';state.view='collection';setNav('');renderCollection();let idx=resume?Number(d.lastIndex||0):0;if(targetKey){const f=d.items.findIndex(x=>x.item_key===targetKey);if(f>=0)idx=f}if(resume||targetKey)setTimeout(()=>scrollToSentence(idx),120)}
function backFromCollection(){render(state.returnView||'learn')}
function collectionTypeLabel(){const d=state.collection;if(d.kind==='my')return 'My Island';if(String(d.collection.source_group||'').startsWith('course:'))return 'Course';return d.collection.is_vocabulary?'Vocabulary':'Island'}
function renderCollection(){clearPositionTracker();const d=state.collection;if(!d)return;state.view='collection';setNav('');setHead(d.collection.name,`${collectionTypeLabel()} · ${d.items.length} câu`);const active=d.activeDailySource;content().innerHTML=`
<div class="collection-head"><div class="collection-head-top"><div><h2>${esc(d.collection.name)}</h2><p>${esc(d.collection.description||d.collection.topic_name||'')}</p></div><div class="collection-head-actions"><button class="btn ghost small" onclick="backFromCollection()">← Quay lại</button>${d.kind==='my'?`<button class="btn secondary small" onclick="manageMyIsland(${d.collection.id})">Quản lý Island</button>`:''}<button class="btn ghost small" onclick="openCollectionSrsMenu()">↻ Ôn tập</button><button class="btn ${active?'ghost':'secondary'} small" ${active?'disabled':''} onclick="setActiveCurrent()">${active?'✓ Bộ học hằng ngày':'Đặt làm bộ hằng ngày'}</button></div></div><div class="tabs"><button class="tab ${state.collectionTab==='list'?'active':''}" onclick="setCollectionTab('list')">Danh sách</button><button class="tab ${state.collectionTab==='shadow'?'active':''}" onclick="setCollectionTab('shadow')">Shadowing</button><button class="tab ${state.collectionTab==='recall'?'active':''}" onclick="setCollectionTab('recall')">Active Recall</button></div></div><div id="collectionBody"></div>`;renderCollectionBody()}
function setCollectionTab(tab){stopAllAudio();clearPositionTracker();state.collectionTab=tab;renderCollection()}
function renderCollectionBody(){if(state.collectionTab==='list')renderListTab();else if(state.collectionTab==='shadow')renderShadowTab();else renderRecallSetup()}
function translationButton(){return `<button class="toggle-chip ${state.translation?'on':''}" onclick="toggleTranslation()">${state.translation?'Ẩn tiếng Việt':'Hiện tiếng Việt'}</button>`}
function srsBadge(x){if(x.suspended)return `<span class="srs-dot suspended">tạm dừng</span>`;if(!x.srs)return '';return `<span class="srs-dot ${x.srs.due_now?'due':''}">${x.srs.due_now?'đến hạn':'SRS'}</span>`}
function sentenceRows(items,shadow=false){return items.map((x,i)=>`<div class="sentence-row" id="sent-${i}" data-index="${i}"><div class="sentence-index">${String(i+1).padStart(2,'0')}</div><button class="row-play" onclick="${shadow?`startShadow(${i})`:`playCollectionAudio(${i})`}" ${x.audio?'':'disabled'}>▶</button><div class="sentence-text"><div class="en">${esc(x.en_us)} ${srsBadge(x)}</div><div class="vi ${state.translation?'':'hidden'}">${esc(x.vi_vn||'')}</div>${x.usage_note?`<div class="notes">Cách dùng: ${esc(x.usage_note)}</div>`:''}</div><div class="row-side"><button class="save-btn ${x.saved?'on':''}" onclick="toggleBookmark('${x.item_key}',${i})" title="Lưu câu">🔖</button><button class="icon-btn srs-menu-btn" onclick="openItemSrs('${x.item_key}')" title="Quản lý ôn tập">⋯</button></div></div>`).join('')}
function fmtDateTime(iso){if(!iso)return '—';try{return new Date(iso).toLocaleString('vi-VN',{dateStyle:'short',timeStyle:'short'})}catch{return iso}}
function fmtSrsNumber(v,digits=2){return v===null||v===undefined?'—':Number(v).toFixed(digits)}
function itemSrsInfoHtml(i){const status=`${esc(i.state)}${i.suspended?' · Tạm dừng':''}`;return `<div class="srs-info-grid"><div><small>Trạng thái</small><b>${status}</b></div><div><small>Ôn tiếp theo</small><b>${fmtDateTime(i.due)}</b></div><div><small>Stability</small><b>${i.stability===null||i.stability===undefined?'—':fmtSrsNumber(i.stability)+' ngày'}</b></div><div><small>Difficulty</small><b>${fmtSrsNumber(i.difficulty)}</b></div><div><small>Lượt ôn</small><b>${i.review_count||0}</b></div><div><small>Số lần quên</small><b>${i.lapse_count||0}</b></div><div><small>Lần ôn gần nhất</small><b>${fmtDateTime(i.last_review)}</b></div><div><small>Lịch sử đã lưu</small><b>${i.history_count||0} lượt</b></div></div>`}
async function openItemSrs(key){try{const i=await api('/api/srs/info?item_key='+encodeURIComponent(key));openModal(`<h2 style="margin-top:0">Quản lý ôn tập</h2><p><b>${esc(i.en_us)}</b></p><p class="muted tiny">${esc(i.vi_vn||'')}</p>${itemSrsInfoHtml(i)}${i.suspended?`<div class="guide-callout">Câu đang tạm dừng nên không xuất hiện trong Daily Study. Resume giữ nguyên lịch FSRS trước đó.</div>`:''}<div class="srs-actions"><button class="btn secondary" ${i.state==='New'||i.suspended?'disabled':''} onclick="runSrsAction('review_now','item','${i.item_key}')">Ôn lại ngay</button><button class="btn danger" ${i.state==='New'?'disabled':''} onclick="runSrsAction('reset','item','${i.item_key}')">Reset về Chưa học</button><button class="btn ghost" onclick="runSrsAction('${i.suspended?'resume':'suspend'}','item','${i.item_key}')">${i.suspended?'Tiếp tục ôn tập':'Tạm dừng ôn tập'}</button></div><p class="muted tiny mt12">Reset chỉ xóa trạng thái/lịch FSRS hiện tại; lịch sử review vẫn được giữ. Nếu câu đang tạm dừng, trạng thái tạm dừng cũng được giữ.</p>`)}catch(e){toast(e.message)}}
async function openCollectionSrsMenu(){if(!state.collection)return;try{const i=await api('/api/srs/info?collection_key='+encodeURIComponent(state.collection.collectionKey));const c=i.counts||{};openModal(`<h2 style="margin-top:0">Ôn tập · ${esc(i.name)}</h2><p class="muted">${i.total} câu duy nhất sau khi gộp câu trùng.</p><div class="srs-info-grid"><div><small>Chưa học</small><b>${c.new||0}</b></div><div><small>Learning</small><b>${c.learning||0}</b></div><div><small>Review</small><b>${c.review||0}</b></div><div><small>Mature</small><b>${c.mature||0}</b></div><div><small>Relearning</small><b>${c.relearning||0}</b></div><div><small>Đến hạn</small><b>${c.due||0}</b></div><div><small>Đã vào SRS</small><b>${c.started||0}</b></div><div><small>Tạm dừng</small><b>${c.suspended||0}</b></div></div><div class="srs-actions"><button class="btn secondary" ${c.started?'':'disabled'} onclick="runSrsAction('review_now','collection','${state.collection.collectionKey}',${i.total})">Ôn lại ngay</button><button class="btn danger" ${c.started?'':'disabled'} onclick="runSrsAction('reset','collection','${state.collection.collectionKey}',${i.total})">Reset về Chưa học</button><button class="btn ghost" onclick="runSrsAction('suspend','collection','${state.collection.collectionKey}',${i.total})">Tạm dừng cả bộ</button><button class="btn ghost" ${c.suspended?'':'disabled'} onclick="runSrsAction('resume','collection','${state.collection.collectionKey}',${i.total})">Tiếp tục cả bộ</button></div><div class="guide-callout">SRS thuộc về câu canonical. Nếu một câu cũng xuất hiện ở bộ khác, thao tác tại đây sẽ thay đổi trạng thái chung của chính câu đó.</div>`)}catch(e){toast(e.message)}}
async function openGroupSrsMenu(groupKey,name='Course'){try{const i=await api('/api/srs/info?group_key='+encodeURIComponent(groupKey));const c=i.counts||{};openModal(`<h2 style="margin-top:0">Ôn tập · ${esc(name||i.name)}</h2><p class="muted">${i.total} câu canonical duy nhất trong phạm vi này.</p><div class="srs-info-grid"><div><small>Chưa học</small><b>${c.new||0}</b></div><div><small>Learning</small><b>${c.learning||0}</b></div><div><small>Review</small><b>${c.review||0}</b></div><div><small>Mature</small><b>${c.mature||0}</b></div><div><small>Relearning</small><b>${c.relearning||0}</b></div><div><small>Đến hạn</small><b>${c.due||0}</b></div><div><small>Đã vào SRS</small><b>${c.started||0}</b></div><div><small>Tạm dừng</small><b>${c.suspended||0}</b></div></div><div class="srs-actions"><button class="btn secondary" ${c.started?'':'disabled'} onclick="runSrsAction('review_now','group','${groupKey}',${i.total})">Ôn lại ngay</button><button class="btn danger" ${c.started?'':'disabled'} onclick="runSrsAction('reset','group','${groupKey}',${i.total})">Reset về Chưa học</button><button class="btn ghost" onclick="runSrsAction('suspend','group','${groupKey}',${i.total})">Tạm dừng</button><button class="btn ghost" ${c.suspended?'':'disabled'} onclick="runSrsAction('resume','group','${groupKey}',${i.total})">Tiếp tục</button></div><div class="guide-callout">Các Unit dùng chung SRS theo canonical sentence. Một câu trùng giữa các Unit chỉ được xử lý một lần.</div>`)}catch(e){toast(e.message)}}
function srsActionConfirm(action,scope,total){if(scope==='item'){if(action==='reset')return confirm('Reset câu này về Chưa học? Lịch sử review vẫn được giữ.');if(action==='suspend')return confirm('Tạm dừng câu này khỏi Daily Study?');return true}const n=Number(total||0);if(action==='review_now')return confirm(`Đưa các câu đã có lịch SRS trong bộ này đến hạn ngay? Bộ có ${n} câu duy nhất. Stability/Difficulty không bị reset.`);if(action==='reset')return confirm(`Reset tiến độ SRS của bộ này về Chưa học? Bộ có ${n} câu duy nhất. Lịch sử review vẫn được giữ.`);if(action==='suspend')return confirm(`Tạm dừng ôn tập cho toàn bộ ${n} câu duy nhất trong bộ này?`);if(action==='resume')return confirm(`Tiếp tục ôn tập cho các câu đang tạm dừng trong bộ này?`);return true}
async function refreshCurrentAfterSrs(){await refreshBoot();if(state.view==='collection'&&state.collection){const d=await api(`/api/collection?kind=${encodeURIComponent(state.collection.kind)}&id=${state.collection.collection.id}`);state.collection=d;renderCollection()}else if(state.view==='saved'){await savedView()}else if(state.view==='search'){const q=el('q')?.value||'';if(q)await doSearch(q)}else if(state.view==='courses'){coursesView()}else if(state.view==='manager'&&state.manager){state.manager=await api(`/api/collection?kind=my&id=${state.manager.collection.id}`);renderManager()}}
async function runSrsAction(action,scope,key,total=1){if(!srsActionConfirm(action,scope,total))return;try{const payload={action};if(scope==='item')payload.item_key=key;else if(scope==='group')payload.group_key=key;else payload.collection_key=key;const r=await post('/api/srs/manage',payload);closeModal();await refreshCurrentAfterSrs();let msg='Đã cập nhật ôn tập';if(action==='review_now')msg=r.affected?`Đã đưa ${r.affected} câu đến hạn ngay`:(r.skipped_suspended?'Không đổi: câu đang tạm dừng':'Không có câu đã vào SRS để đưa đến hạn');if(action==='reset')msg=`Đã reset ${r.affected} câu về Chưa học`;if(action==='suspend')msg=`Đã tạm dừng ${r.affected} câu`;if(action==='resume')msg=`Đã tiếp tục ${r.affected} câu`;toast(msg)}catch(e){toast(e.message)}}
function renderListTab(){const d=state.collection,b=el('collectionBody');b.innerHTML=`<div class="toolbar"><div class="toolbar-left"><button class="btn secondary small" onclick="playCollectionAudio(0,true)">▶ Nghe từ đầu</button>${translationButton()}<button class="toggle-chip ${state.listAuto?'on':''}" onclick="toggleListAuto()">Auto next: ${state.listAuto?'ON':'OFF'}</button><label class="tiny muted">Nghỉ <select class="select compact" onchange="setListAutoDelay(this.value)">${[0,.5,1,2,3,5].map(v=>`<option value="${v}" ${Number(state.listAutoDelay)===v?'selected':''}>${v}s</option>`).join('')}</select></label></div><div class="toolbar-right"><span class="tiny muted">Đọc từ trên xuống · bấm 🔊 ở bất kỳ câu nào</span></div></div><div class="sentence-list">${sentenceRows(d.items,false)}</div>`;bindPositionTracker();if(state.audioMode==='list'&&state.listAudioIndex>=0)markPlaying(state.listAudioIndex)}
function toggleTranslation(){state.translation=!state.translation;if(state.view==='collection')renderCollection();else if(state.recall)renderRecallCard()}
async function toggleBookmark(key,index=null){try{const r=await post('/api/bookmark',{item_key:key});if(state.collection){for(const x of state.collection.items)if(x.item_key===key)x.saved=r.saved;if(state.view==='collection')renderCollection()}toast(r.saved?'Đã lưu câu':'Đã bỏ lưu');await refreshBoot()}catch(e){toast(e.message)}}
async function savePosition(index){if(!state.collection)return;try{await post('/api/position',{collection_key:state.collection.collectionKey,index})}catch{}}
function bindPositionTracker(){clearPositionTracker();state.posHandler=()=>{clearTimeout(state.posTimer);state.posTimer=setTimeout(()=>{if(state.view!=='collection'||state.collectionTab!=='list')return;const rows=[...document.querySelectorAll('.sentence-row')];let idx=0;for(const r of rows){const rect=r.getBoundingClientRect();if(rect.bottom>145){idx=Number(r.dataset.index||0);break}}savePosition(idx)},500)};window.addEventListener('scroll',state.posHandler,{passive:true})}
function scrollToSentence(i){const x=el(`sent-${Math.max(0,i)}`);if(x)x.scrollIntoView({behavior:'smooth',block:'center'})}
async function setActiveCurrent(){try{await post('/api/active-source',{collection_key:state.collection.collectionKey});state.collection.activeDailySource=true;await refreshBoot();renderCollection();toast('Đã đặt làm nguồn câu mới hằng ngày')}catch(e){toast(e.message)}}

function showPlayer(index){const d=state.collection,x=d?.items[index];if(!x)return;const bp=el('bottomPlayer');bp.classList.remove('hidden');bp.innerHTML=`<div class="player-title"><b>${esc(x.en_us)}</b><small>${index+1}/${d.items.length}</small></div><div class="player-controls"><button class="player-btn" onclick="playerPrev()">←</button><button class="player-btn primary-player" id="playerToggle" onclick="togglePlayerPlay()">${player().paused?'▶':'❚❚'}</button><button class="player-btn" onclick="playerNext()">→</button></div><div class="player-options"><select onchange="setListSpeed(this.value)">${[.75,.9,1,1.1,1.25].map(v=>`<option value="${v}" ${Number(state.listSpeed)===v?'selected':''}>${v}×</option>`).join('')}</select><button onclick="toggleListAuto()">Auto ${state.listAuto?'ON':'OFF'}</button><select title="Khoảng nghỉ trước câu tiếp theo" onchange="setListAutoDelay(this.value)">${[0,.5,1,2,3,5].map(v=>`<option value="${v}" ${Number(state.listAutoDelay)===v?'selected':''}>Next ${v}s</option>`).join('')}</select></div>`}
function hidePlayer(){el('bottomPlayer').classList.add('hidden')}
function markPlaying(index,cls='playing'){document.querySelectorAll('.sentence-row').forEach(r=>r.classList.remove('playing','shadowing'));const x=el(`sent-${index}`);if(x){x.classList.add(cls);if(x.getBoundingClientRect().bottom>window.innerHeight-110||x.getBoundingClientRect().top<110)x.scrollIntoView({behavior:'smooth',block:'center'})}}
async function playCollectionAudio(index,forceAuto=false){if(!state.collection)return;const x=state.collection.items[index];if(!x?.audio){toast('Câu này chưa có audio');return}clearTimeout(state.listAutoTimer);state.listAutoTimer=null;stopShadow(false);state.audioMode='list';state.listAudioIndex=index;if(forceAuto)state.listAuto=true;const p=player();p.src=x.audio;p.playbackRate=state.listSpeed;try{await p.play();markPlaying(index);showPlayer(index);savePosition(index)}catch{toast('Không phát được audio')}}
function toggleListAuto(){state.listAuto=!state.listAuto;if(!state.listAuto){clearTimeout(state.listAutoTimer);state.listAutoTimer=null}if(state.view==='collection'&&state.collectionTab==='list')renderCollection();else if(state.listAudioIndex>=0)showPlayer(state.listAudioIndex)}
async function setListAutoDelay(v){state.listAutoDelay=Number(v);try{await post('/api/setting',{key:'list_auto_delay',value:state.listAutoDelay});state.boot.settings.list_auto_delay=String(state.listAutoDelay)}catch{}if(state.listAudioIndex>=0)showPlayer(state.listAudioIndex)}
function setListSpeed(v){state.listSpeed=Number(v);player().playbackRate=state.listSpeed;if(state.listAudioIndex>=0)showPlayer(state.listAudioIndex)}
function togglePlayerPlay(){const p=player();if(p.paused)p.play().catch(()=>toast('Không phát được audio'));else p.pause();if(state.listAudioIndex>=0)showPlayer(state.listAudioIndex)}
function playerPrev(){if(state.listAudioIndex>0)playCollectionAudio(state.listAudioIndex-1)}
function playerNext(){if(state.collection&&state.listAudioIndex<state.collection.items.length-1)playCollectionAudio(state.listAudioIndex+1)}
player().onplay=()=>{if(state.audioMode==='list'&&state.listAudioIndex>=0)showPlayer(state.listAudioIndex)};
player().onpause=()=>{if(state.audioMode==='list'&&state.listAudioIndex>=0)showPlayer(state.listAudioIndex)};
player().onended=()=>{if(state.audioMode==='shadow'){shadowEnded();return}if(state.audioMode==='list'){if(state.listAuto&&state.collection&&state.listAudioIndex<state.collection.items.length-1){clearTimeout(state.listAutoTimer);state.listAutoTimer=setTimeout(()=>{state.listAutoTimer=null;if(state.listAuto&&state.audioMode==='list')playCollectionAudio(state.listAudioIndex+1)},Math.max(0,state.listAutoDelay)*1000);if(state.listAudioIndex>=0)showPlayer(state.listAudioIndex);return}if(state.listAudioIndex>=0)showPlayer(state.listAudioIndex)}};

function renderShadowTab(){const d=state.collection,b=el('collectionBody');b.innerHTML=`<div class="shadow-panel"><div class="shadow-controls"><button class="btn primary small" onclick="startShadow(${Math.max(0,state.shadow.index||0)})">▶ Start</button><button class="btn ghost small" onclick="stopShadow()">■ Stop</button><label>Speed <select class="select" onchange="shadowSetting('shadow_speed',this.value)">${[.75,.9,1,1.1,1.25].map(v=>`<option value="${v}" ${Number(state.shadow.speed)===v?'selected':''}>${v}×</option>`).join('')}</select></label><label>Lặp <select class="select" onchange="shadowSetting('shadow_repeat',this.value)">${[1,2,3,5].map(v=>`<option value="${v}" ${Number(state.shadow.repeat)===v?'selected':''}>${v}×</option>`).join('')}</select></label><label>Nghỉ <select class="select" onchange="shadowSetting('shadow_pause',this.value)">${[0.5,1,2,3,5].map(v=>`<option value="${v}" ${Number(state.shadow.pause)===v?'selected':''}>${v}s</option>`).join('')}</select></label><button class="toggle-chip ${state.shadow.autoNext?'on':''}" onclick="toggleShadowAuto()">Auto next ${state.shadow.autoNext?'ON':'OFF'}</button>${translationButton()}</div><div class="shadow-status" id="shadowStatus">Nghe → nhại lại trong khoảng nghỉ → lặp → câu tiếp theo.</div></div><div class="sentence-list">${sentenceRows(d.items,true)}</div>`;if(state.shadow.running){markPlaying(state.shadow.index,'shadowing');updateShadowStatus()}}
async function shadowSetting(key,v){if(key==='shadow_speed')state.shadow.speed=Number(v);if(key==='shadow_repeat')state.shadow.repeat=Number(v);if(key==='shadow_pause')state.shadow.pause=Number(v);try{await post('/api/setting',{key,value:v});state.boot.settings[key]=String(v)}catch{}}
function toggleShadowAuto(){state.shadow.autoNext=!state.shadow.autoNext;renderCollection()}
function updateShadowStatus(){const x=el('shadowStatus');if(x&&state.shadow.running)x.textContent=`Đang câu ${state.shadow.index+1}/${state.collection.items.length} · lượt ${state.shadow.repeatDone+1}/${state.shadow.repeat}`}
async function startShadow(index=0){if(!state.collection)return;stopShadow(false);state.shadow.running=true;state.shadow.index=Math.max(0,Math.min(Number(index),state.collection.items.length-1));state.shadow.repeatDone=0;state.audioMode='shadow';await playShadowCurrent()}
async function playShadowCurrent(){if(!state.shadow.running)return;const x=state.collection.items[state.shadow.index];if(!x?.audio){return shadowAdvance()}const p=player();p.src=x.audio;p.playbackRate=state.shadow.speed;markPlaying(state.shadow.index,'shadowing');updateShadowStatus();try{await p.play();savePosition(state.shadow.index)}catch{shadowAdvance()}}
function shadowEnded(){if(!state.shadow.running)return;state.shadow.repeatDone++;if(state.shadow.repeatDone<state.shadow.repeat){state.shadow.timer=setTimeout(playShadowCurrent,state.shadow.pause*1000)}else shadowAdvance()}
function shadowAdvance(){if(!state.shadow.running)return;state.shadow.repeatDone=0;if(state.shadow.autoNext&&state.shadow.index<state.collection.items.length-1){state.shadow.index++;state.shadow.timer=setTimeout(playShadowCurrent,state.shadow.pause*1000)}else stopShadow()}
function stopShadow(show=true){clearTimeout(state.shadow.timer);state.shadow.timer=null;if(state.shadow.running)player().pause();state.shadow.running=false;if(state.audioMode==='shadow')state.audioMode=null;document.querySelectorAll('.sentence-row').forEach(r=>r.classList.remove('shadowing'));if(show&&el('shadowStatus'))el('shadowStatus').textContent='Đã dừng. Chọn một câu hoặc Start để chạy lại.'}

function renderRecallSetup(){const b=el('collectionBody'),m=state.recallMode;b.innerHTML=`<div class="recall-setup"><h2>Active Recall</h2><p>Thẻ chỉ dùng ở đây: tự nhớ/tự nói trước, sau đó mới hiện đáp án và đánh giá để cập nhật FSRS.</p><div class="choice-grid"><button class="choice ${m==='vi_en'?'active':''}" onclick="chooseRecallMode('vi_en')"><b>VI → EN</b><small>Nhìn nghĩa Việt → tự nói câu English.</small></button><button class="choice ${m==='audio_en'?'active':''}" onclick="chooseRecallMode('audio_en')"><b>Audio → EN</b><small>Chỉ nghe → tự nhớ và nói lại English.</small></button><button class="choice ${m==='en_meaning'?'active':''}" onclick="chooseRecallMode('en_meaning')"><b>EN → Meaning</b><small>Nhìn English → tự nhớ nghĩa.</small></button></div><div class="toolbar"><div class="toolbar-left"><label class="tiny muted">Số câu <select id="recallCount" class="select"><option value="10">10</option><option value="20">20</option><option value="all" selected>Tất cả</option></select></label></div><button class="btn primary" onclick="startCollectionRecall()">Bắt đầu Recall</button></div><div class="info-strip mt12">Chỉ khi bạn bấm <b>Quên / Khó / Nhớ / Dễ</b> thì lịch FSRS mới thay đổi. Đọc danh sách và Shadowing không làm thay đổi SRS.</div></div>`}
async function chooseRecallMode(m){state.recallMode=m;try{await post('/api/setting',{key:'recall_mode',value:m});state.boot.settings.recall_mode=m}catch{}renderRecallSetup()}
function dedupeItems(items){const seen=new Set();return items.filter(x=>{if(seen.has(x.item_key))return false;seen.add(x.item_key);return true})}
function startCollectionRecall(){const v=el('recallCount')?.value||'all';let items=dedupeItems(state.collection.items);if(v!=='all')items=items.slice(0,Number(v));startRecallSession(items,'free_recall',state.collection.collection.name,'collection')}
function startRecallSession(items,sourceMode,title,doneType='collection',meta={}){stopAllAudio();state.recall={items:[...items],index:0,revealed:false,sourceMode,title,doneType,meta,results:{again:0,hard:0,good:0,easy:0,skipped:0},initialCount:items.length};state.view='recall';renderRecallCard()}
function currentRecall(){return state.recall?.items[state.recall.index]}
function prepareRecallCurrent(){const s=state.recall;if(!s||s.index>=s.items.length)return false;const now=Date.now()/1000;let j=s.index;while(j<s.items.length&&s.items[j]._dueTs&&s.items[j]._dueTs>now)j++;if(j>=s.items.length)return false;if(j!==s.index){const t=s.items[s.index];s.items[s.index]=s.items[j];s.items[j]=t}return true}
function recallPrompt(x){if(state.recallMode==='vi_en')return {label:'VI → EN',main:x.vi_vn||'(Không có nghĩa Việt)',hint:'Tự nói câu tiếng Anh trước khi hiện đáp án.'};if(state.recallMode==='audio_en')return {label:'AUDIO → EN',main:'Nghe audio và tự nói lại câu tiếng Anh.',hint:x.audio?'Bấm Play nếu muốn nghe lại.':'Câu này chưa có audio.'};return {label:'EN → MEANING',main:x.en_us,hint:'Tự nhớ nghĩa tiếng Việt trước khi hiện đáp án.'}}
function renderRecallCard(){const s=state.recall;if(!s)return;if(s.index>=s.items.length||!prepareRecallCurrent())return finishRecall();const x=currentRecall(),p=recallPrompt(x),pct=Math.round(s.index/Math.max(1,s.items.length)*100);setNav(s.sourceMode==='daily'||s.sourceMode==='daily_extra'?'review':'');setHead(s.title,'Active Recall · đánh giá sẽ cập nhật FSRS');content().innerHTML=`<div class="recall-wrap"><div class="session-head"><button class="btn ghost small" onclick="exitRecall()">← Thoát</button><div class="counter">${s.index+1} / ${s.items.length}</div></div><div class="session-progress"><div style="width:${pct}%"></div></div><div class="recall-card"><div class="recall-label">${p.label}</div><div class="recall-prompt">${esc(p.main)}</div>${state.recallMode==='audio_en'?`<div class="recall-audio"><button class="big-play" onclick="playRecallAudio()" ${x.audio?'':'disabled'}>▶</button></div>`:''}<div class="recall-hint">${esc(p.hint)}</div>${s.revealed?`<div class="recall-answer"><div class="en">${esc(x.en_us)}</div><div class="vi">${esc(x.vi_vn||'')}</div>${x.audio?`<div class="recall-audio"><button class="icon-btn" style="margin:auto" onclick="playRecallAudio()">▶</button></div>`:''}<div class="ratings"><button class="rate again" onclick="rateRecall(1)">Quên<small>Again</small></button><button class="rate hard" onclick="rateRecall(2)">Khó<small>Hard</small></button><button class="rate good" onclick="rateRecall(3)">Nhớ<small>Good</small></button><button class="rate easy" onclick="rateRecall(4)">Dễ<small>Easy</small></button></div></div>`:`<button class="btn primary" onclick="revealRecall()">Hiện đáp án</button>`}<button class="link-btn mt12" onclick="skipRecall()">Bỏ qua, không tính SRS</button></div></div>`;if(state.recallMode==='audio_en'&&!s.revealed&&x.audio)setTimeout(playRecallAudio,180)}
function revealRecall(){state.recall.revealed=true;renderRecallCard()}
async function playRecallAudio(){const x=currentRecall();if(!x?.audio){toast('Câu này chưa có audio');return}state.audioMode='recall';const p=player();p.src=x.audio;p.playbackRate=1;try{await p.play()}catch{toast('Không phát được audio')}}
async function rateRecall(rating){const s=state.recall,x=currentRecall();try{const r=await post('/api/review',{item_key:x.item_key,rating,source_mode:s.sourceMode});const k=['','again','hard','good','easy'][rating];s.results[k]++;x.srs=r.srs;if(r.stats){Object.assign(state.boot.stats,r.stats);updateDueBadge()}if(r.learning_pending){s.items.push({...x,_requeue:true,_dueTs:r.due_ts})}s.index++;s.revealed=false;renderRecallCard();if(r.learning_pending)toast(`Đã hẹn lại sau ${formatDueShort(r.due_in_seconds)}`)}catch(e){toast(e.message)}}
async function finishRecall(){const s=state.recall;if(!s||s.finishing)return;s.finishing=true;try{await refreshBoot()}catch(e){toast(e.message)}renderRecallDone()}
function formatDueShort(sec){sec=Math.max(0,Math.round(Number(sec)||0));if(sec<90)return `${sec}s`;const m=Math.round(sec/60);if(m<90)return `${m} phút`;return `${Math.round(m/60)} giờ`}
function skipRecall(){state.recall.results.skipped++;state.recall.index++;state.recall.revealed=false;renderRecallCard()}
function exitRecall(){const d=state.recall?.doneType;state.recall=null;if(d==='daily')render('review');else if(state.collection){state.view='collection';renderCollection()}else render('home')}
function renderRecallDone(){const s=state.recall,r=s.results,pending=s.items.slice(s.index).filter(x=>x._dueTs&&x._dueTs>Date.now()/1000).length;setHead('Hoàn thành','Phiên Active Recall đã kết thúc.');content().innerHTML=`<div class="session-done"><h2>Hoàn thành</h2><p class="muted">${s.initialCount} câu ban đầu. Learning/Relearning chỉ xuất hiện lại khi thực sự đến hạn.</p>${pending?`<div class="info-strip mt12"><b>${pending} lượt học lại</b> đã được FSRS hẹn sau vài phút. Chúng sẽ xuất hiện trong Review khi đến hạn; app không ép hiện sớm.</div>`:''}<div class="done-stats"><div><strong>${r.again}</strong><small>Quên</small></div><div><strong>${r.hard}</strong><small>Khó</small></div><div><strong>${r.good}</strong><small>Nhớ</small></div><div><strong>${r.easy}</strong><small>Dễ</small></div></div>${s.doneType==='daily'?`<div class="section-actions" style="justify-content:center"><button class="btn secondary" onclick="startDaily('10')">Học thêm 10</button><button class="btn secondary" onclick="startDaily('20')">Học thêm 20</button><button class="btn secondary" onclick="startDaily('all')">Học hết Island</button><button class="btn ghost" onclick="render('home')">Về Home</button></div>`:`<div class="section-actions" style="justify-content:center"><button class="btn primary" onclick="returnAfterRecall()">Quay lại Island</button></div>`}</div>`}
function returnAfterRecall(){state.recall=null;if(state.collection){state.view='collection';renderCollection()}else render('home')}

function reviewOverview(){const s=state.boot.stats,a=state.boot.activeSource,lim=state.boot.settings.new_per_day;setHead('Review','Daily Study = ôn đến hạn + câu mới theo kế hoạch.');content().innerHTML=`<div class="hero"><div><h2>Daily Study</h2><p>Ôn đến hạn không bị giới hạn cứng. Câu mới lấy theo đúng thứ tự của Island đang chọn.</p><div class="hero-actions"><button class="btn secondary" onclick="startDaily()">Bắt đầu hôm nay</button><button class="btn" style="background:rgba(255,255,255,.14);color:#fff" onclick="startDaily('0')">Chỉ ôn đến hạn</button></div></div><div class="daily-box"><div class="daily-numbers"><div><strong>${s.dueToday}</strong><small>Đến hạn</small></div><div><strong>${s.newToday}</strong><small>Câu mới còn lại</small></div></div>${dailySourceControl(a)}</div></div><div class="section-head"><div><h2>Học tự do hơn kế hoạch</h2><p>Không bị khóa bởi giới hạn ngày.</p></div></div><div class="info-strip"><div class="section-actions"><button class="btn secondary small" onclick="startDaily('10')">+10 câu mới</button><button class="btn secondary small" onclick="startDaily('20')">+20 câu mới</button><button class="btn secondary small" onclick="startDaily('all')">Học hết phần còn lại</button></div><p class="tiny muted mt8">Free Study không tự thay lịch SRS. Chỉ khi bạn chủ động đánh giá trong Active Recall thì câu mới được cập nhật lịch.</p></div><div class="section-head"><div><h2>Logic SRS</h2></div></div><div class="info-strip">FSRS dùng <b>Quên / Khó / Nhớ / Dễ</b>. Câu mới bắt đầu ở Learning; câu quên khi đã Review chuyển sang Relearning và được hẹn lại theo bước Relearning. Desired retention hiện tại: <b>${Math.round(Number(state.boot.settings.desired_retention||.9)*100)}%</b>.</div>`}
async function startDaily(extra=null){try{const q=extra===null?'':`?extra=${encodeURIComponent(extra)}`;const d=await api('/api/session/daily'+q);if(!d.items.length){setHead('Daily Study','Không còn câu trong phiên này.');content().innerHTML=`<div class="session-done"><h2>Không có câu cần học</h2><p class="muted">Không có review đến hạn và không còn câu mới theo lựa chọn hiện tại.</p><div class="section-actions" style="justify-content:center"><button class="btn secondary" onclick="render('learn')">Chọn Island khác</button><button class="btn ghost" onclick="render('home')">Home</button></div></div>`;return}startRecallSession(dedupeItems(d.items),extra===null?'daily':'daily_extra',extra===null?'Daily Study':'Free Study · học thêm','daily',{dueCount:d.dueCount,newCount:d.newCount,activeSource:d.activeSource})}catch(e){toast(e.message)}}

function myIslandsView(){setHead('My Islands','Tạo bộ câu riêng từ thư viện hoặc câu tự thêm + audio riêng.');const arr=state.boot.myIslands||[];content().innerHTML=`<div class="section-head"><div><h2>My Islands</h2><p>Mỗi Island có thể dùng List, Shadowing, Active Recall và FSRS như Island gốc.</p></div><button class="btn primary" onclick="openCreateIslandModal()">+ Create Island</button></div>${arr.length?`<div class="my-grid">${arr.map(x=>`<div class="my-card" onclick="openCollection('my',${x.id},'my',false)"><h3>${esc(x.name)}</h3><p>${esc(x.description||'Island cá nhân')}</p><footer>${x.sentence_count||0} câu · <button class="link-btn" onclick="event.stopPropagation();manageMyIsland(${x.id})">Quản lý</button></footer></div>`).join('')}</div>`:`<div class="empty">Chưa có My Island. Tạo một Island để gom các câu theo nhu cầu của bạn.</div>`}`}
function openCreateIslandModal(){openModal(`<h2 style="margin-top:0">Create Island</h2><div class="form-row"><label>Tên Island</label><input id="newIslandName" class="field" placeholder="Ví dụ: Travel English"></div><div class="form-row"><label>Mô tả</label><textarea id="newIslandDesc" class="field textarea" placeholder="Tùy chọn"></textarea></div><div class="form-actions"><button class="btn primary" onclick="createIsland()">Tạo Island</button><button class="btn ghost" onclick="closeModal()">Hủy</button></div>`);setTimeout(()=>el('newIslandName')?.focus(),100)}
async function createIsland(){try{const r=await post('/api/my-island/create',{name:el('newIslandName').value,description:el('newIslandDesc').value});closeModal();await refreshBoot();manageMyIsland(r.id)}catch(e){toast(e.message)}}
function openModal(html){state.modalReturnFocus=document.activeElement;el('modalBody').innerHTML=html;const modal=el('modal');modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');const heading=el('modalBody').querySelector('h2');if(heading){heading.tabIndex=-1;setTimeout(()=>heading.focus(),0)}}
function closeModal(){if(state.bulkImport?.previewOpen){post('/api/bulk-audio/cancel',{token:state.bulkImport.token}).catch(()=>{});state.bulkImport=null}const modal=el('modal');modal.classList.add('hidden');modal.setAttribute('aria-hidden','true');el('modalBody').innerHTML='';if(state.modalReturnFocus?.focus)state.modalReturnFocus.focus();state.modalReturnFocus=null}
async function manageMyIsland(id){stopAllAudio();clearPositionTracker();const d=await api(`/api/collection?kind=my&id=${id}`);state.manager=d;state.view='manager';setNav('my');setHead(d.collection.name,'Quản lý nội dung My Island');renderManager()}
async function openManagerCollectionSrs(id){await openCollection('my',id,'my',false);await openCollectionSrsMenu()}
function renderManager(){const d=state.manager;content().innerHTML=`<div class="manager-layout"><div class="manager-panel"><div class="section-head" style="margin-top:0"><div><h2>Nội dung Island</h2><p>Kéo các dòng để đổi thứ tự.</p></div><div class="section-actions"><button class="btn secondary small" onclick="openCollection('my',${d.collection.id},'my',false)">Mở học</button><button class="btn ghost small" onclick="openManagerCollectionSrs(${d.collection.id})">Ôn tập</button><button class="btn danger small" onclick="deleteIsland(${d.collection.id})">Xóa Island</button></div></div><div class="form-row"><label>Tên</label><input id="editIslandName" class="field" value="${esc(d.collection.name)}"></div><div class="form-row"><label>Mô tả</label><input id="editIslandDesc" class="field" value="${esc(d.collection.description||'')}"></div><button class="btn ghost small" onclick="saveIslandInfo(${d.collection.id})">Lưu thông tin</button><div class="member-list mt12" id="memberList">${d.items.length?d.items.map(x=>`<div class="member-row" draggable="true" data-key="${x.item_key}"><div class="drag-handle">≡</div><div><div class="en">${esc(x.en_us)}</div><div class="vi">${esc(x.vi_vn||'')}${x.is_custom?' · câu tự thêm':''}${x.audio_key?` · ${esc(x.audio_key)}`:''}${!x.audio?' · ⚠ chưa audio':''}</div></div><div class="result-actions"><button class="icon-btn srs-menu-btn" onclick="openItemSrs('${x.item_key}')" title="Quản lý ôn tập">⋯</button><button class="icon-btn" onclick="removeFromIsland(${d.collection.id},'${x.item_key}')">×</button></div></div>`).join(''):`<div class="empty">Island đang trống.</div>`}</div></div><div><div class="manager-panel"><h3>Import hàng loạt XLSX</h3><p class="muted tiny">1 file XLSX → thêm nhiều câu vào Island này. Audio Key dùng để gắn audio hàng loạt ngay hoặc bổ sung sau.</p><div class="section-actions"><a class="btn secondary small no-underline" href="/template/my-island.xlsx">↓ Tải file XLSX mẫu</a><button class="btn ghost small" onclick="render('guide');setTimeout(()=>document.getElementById('g10')?.scrollIntoView(),100)">Xem hướng dẫn</button></div><div class="form-row"><label>Chọn XLSX</label><input id="islandXlsx" class="field" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><button class="btn primary small" onclick="importIslandXlsx(${d.collection.id})">Import XLSX</button><hr class="soft-line"><h3>Bổ sung audio hàng loạt</h3><p class="muted tiny">ZIP và folder được xử lý trực tiếp/stream theo Audio Key; app hiển thị báo cáo trước khi import.</p><div class="section-actions"><button class="btn secondary small" onclick="beginBulkAudio('my',${d.collection.id},'zip')">Chọn ZIP audio</button><button class="btn ghost small" onclick="beginBulkAudio('my',${d.collection.id},'folder')">Chọn folder audio</button><button class="btn ghost small" onclick="showMissingAudio(${d.collection.id})">Xem câu thiếu audio</button></div></div><div class="manager-panel mt12"><h3>Thêm từ toàn bộ thư viện</h3><input id="managerQ" class="field" placeholder="Tìm English hoặc tiếng Việt..."><div id="managerResults" class="manager-search-results"></div></div><div class="manager-panel mt12"><h3>Tự thêm câu</h3><div class="form-row"><label>English *</label><textarea id="customEn" class="field textarea"></textarea></div><div class="form-row"><label>Vietnamese</label><textarea id="customVi" class="field textarea"></textarea></div><div class="form-row"><label>Audio Key (tùy chọn)</label><input id="customAudioKey" class="field" placeholder="Ví dụ T001"></div><div class="form-row"><label>Audio (tùy chọn)</label><input id="customAudio" class="field" type="file" accept="audio/*"><small class="muted tiny">MP3/WAV/M4A/AAC/OGG/WEBM · tối đa 25 MB.</small></div><button class="btn primary small" onclick="createCustomInIsland(${d.collection.id})">+ Thêm câu</button></div></div></div>`;bindManagerDrag();const q=el('managerQ');let t;q.oninput=()=>{clearTimeout(t);t=setTimeout(()=>managerSearch(q.value),250)}}
async function saveIslandInfo(id){try{await post('/api/my-island/update',{id,name:el('editIslandName').value,description:el('editIslandDesc').value});await refreshBoot();toast('Đã lưu')}catch(e){toast(e.message)}}
async function deleteIsland(id){if(!confirm('Xóa My Island này? Câu chuẩn và SRS không bị xóa.'))return;try{await post('/api/my-island/delete',{id});await refreshBoot();render('my');toast('Đã xóa Island')}catch(e){toast(e.message)}}
async function managerSearch(q){const box=el('managerResults');if(!box)return;if(q.trim().length<2){box.innerHTML='';return}try{const d=await api('/api/search?q='+encodeURIComponent(q));box.innerHTML=d.items.slice(0,30).map(x=>`<div class="manager-result"><b>${esc(x.en_us)}</b><p>${esc(x.vi_vn||'')}</p><button class="btn secondary small" onclick="addToIsland(${state.manager.collection.id},'${x.item_key}')">+ Add</button></div>`).join('')||'<div class="muted tiny">Không tìm thấy.</div>'}catch(e){box.textContent=e.message}}
async function addToIsland(id,key){try{const r=await post('/api/my-island/add',{id,item_key:key});if(r.already)toast('Câu đã có trong Island');else toast('Đã thêm');await reloadManager(id)}catch(e){toast(e.message)}}
async function removeFromIsland(id,key){try{await post('/api/my-island/remove',{id,item_key:key});await reloadManager(id)}catch(e){toast(e.message)}}
async function reloadManager(id){state.manager=await api(`/api/collection?kind=my&id=${id}`);await refreshBoot();renderManager()}
function bindManagerDrag(){const list=el('memberList');if(!list)return;let dragged=null;list.querySelectorAll('.member-row').forEach(row=>{row.addEventListener('dragstart',e=>{dragged=row;row.classList.add('dragging');e.dataTransfer.effectAllowed='move'});row.addEventListener('dragend',()=>{row.classList.remove('dragging');dragged=null});row.addEventListener('dragover',e=>e.preventDefault());row.addEventListener('drop',async e=>{e.preventDefault();if(!dragged||dragged===row)return;const rect=row.getBoundingClientRect(),after=e.clientY>rect.top+rect.height/2;list.insertBefore(dragged,after?row.nextSibling:row);const keys=[...list.querySelectorAll('.member-row')].map(x=>x.dataset.key);try{await post('/api/my-island/reorder',{id:state.manager.collection.id,item_keys:keys});toast('Đã đổi thứ tự')}catch(err){toast(err.message)}})})}
function fileToBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',',2)[1]||'');r.onerror=reject;r.readAsDataURL(file)})}
async function importIslandXlsx(id){const f=el('islandXlsx')?.files?.[0];if(!f){toast('Hãy chọn file XLSX');return}try{toast('Đang import XLSX...');const xlsx_data=await fileToBase64(f);const r=await post('/api/my-island/import-xlsx',{id,xlsx_data});await reloadManager(id);openModal(`<h2>Import hoàn tất</h2><div class="import-report"><p><b>Đã thêm:</b> ${r.added} câu</p><p><b>Chưa có audio:</b> ${r.missingAudio}</p><p><b>Audio Key tự tạo:</b> ${r.generatedAudioKeys}</p>${r.warnings?.length?`<p><b>Lưu ý:</b><br>${r.warnings.map(esc).join('<br>')}</p>`:''}</div><p class="muted tiny">Bây giờ có thể dùng Bulk Audio để gắn hàng trăm file cùng lúc.</p>`)}catch(e){toast(e.message)}}
function pickBrowserAudio(mode){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=mode==='zip'?'.zip,application/zip':'audio/*';if(mode==='folder'){input.multiple=true;input.webkitdirectory=true}input.onchange=()=>resolve([...(input.files||[])]);input.click()})}
async function stageBrowserBulkAudio(scope,target,mode){const files=await pickBrowserAudio(mode);if(!files.length)return null;if(mode==='zip'){const response=await fetch(`/api/bulk-audio/zip?scope=${encodeURIComponent(scope)}&target=${encodeURIComponent(target)}`,{method:'POST',headers:{'Content-Type':'application/zip'},body:files[0]});if(!response.ok)throw new Error((await response.json()).error||'Không thể tải ZIP');return response.json()}let session=null;try{session=await post('/api/bulk-audio/start',{scope,target});for(let i=0;i<files.length;i++){toast(`Đang stream audio ${i+1}/${files.length}...`);const response=await fetch(`/api/bulk-audio/file?token=${encodeURIComponent(session.token)}&name=${encodeURIComponent(files[i].name)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:files[i]});if(!response.ok)throw new Error((await response.json()).error||'Không thể tải audio')}return await post('/api/bulk-audio/preview',{token:session.token})}catch(error){if(session?.token)post('/api/bulk-audio/cancel',{token:session.token}).catch(()=>{});throw error}}
async function beginBulkAudio(scope,target,mode){try{toast(mode==='zip'?'Đang kiểm tra ZIP audio...':'Đang kiểm tra folder audio...');let report;if(window.pywebview?.api?.pick_bulk_audio){report=await window.pywebview.api.pick_bulk_audio(scope,String(target),mode);if(report?.cancelled)return;if(!report?.ok)throw new Error(report?.error||'Không thể chọn audio')}else report=await stageBrowserBulkAudio(scope,target,mode);if(!report)return;state.bulkImport={scope,target,token:report.token,previewOpen:true};openModal(`<h2>Báo cáo trước khi import</h2><div class="import-report"><p><b>Khớp:</b> ${report.matched}</p><p><b>Còn thiếu sau import:</b> ${report.missing}</p><p><b>Không khớp:</b> ${report.unmatchedCount||0}</p><p><b>Tên trùng:</b> ${report.duplicateCount||0}</p><p><b>Xung đột:</b> ${report.conflictCount||0}</p></div>${report.unmatched?.length?`<details><summary>File không khớp</summary><div class="tiny muted code-list">${report.unmatched.map(esc).join('<br>')}</div></details>`:''}<div class="form-actions"><button class="btn primary" ${report.matched?'':'disabled'} onclick="confirmBulkAudio()">Import ${report.matched} audio</button><button class="btn ghost" onclick="closeModal()">Hủy</button></div>`)}catch(e){toast(e.message)}}
async function confirmBulkAudio(){const current=state.bulkImport;if(!current)return;try{toast('Đang áp dụng audio...');const result=await post('/api/bulk-audio/confirm',{token:current.token});current.previewOpen=false;state.bulkImport=null;closeModal();if(current.scope==='my')await reloadManager(Number(current.target));else{await refreshBoot();openCourse(String(current.target))}openModal(`<h2>Bulk Audio hoàn tất</h2><div class="import-report"><p><b>Đã import:</b> ${result.imported}</p><p><b>Còn thiếu:</b> ${result.missing}</p>${result.available!==undefined?`<p><b>Audio sẵn sàng:</b> ${result.available}</p>`:''}</div>`)}catch(e){toast(e.message)}}
async function showMissingAudio(id){try{const d=await api(`/api/my-island/missing-audio?id=${id}`);openModal(`<h2>Câu chưa có audio (${d.items.length})</h2>${d.items.length?`<div class="missing-list">${d.items.slice(0,300).map(x=>`<div><b>${esc(x.audio_key||'—')}</b> · ${esc(x.en_us)}${x.audio_expected?` <span class="muted">→ ${esc(x.audio_expected)}</span>`:''}</div>`).join('')}</div>`:'<p>Island đã đủ audio.</p>'}`)}catch(e){toast(e.message)}}
async function createCustomInIsland(id){const en=el('customEn').value,vi=el('customVi').value,file=el('customAudio').files[0];try{let audio_data=null,audio_name='',audio_type='';if(file){toast('Đang đọc audio...');audio_data=await fileToBase64(file);audio_name=file.name;audio_type=file.type}await post('/api/custom/create',{en_us:en,vi_vn:vi,audio_key:el('customAudioKey')?.value||'',audio_data,audio_name,audio_type,island_id:id});toast('Đã thêm câu tự tạo');await reloadManager(id)}catch(e){toast(e.message)}}

async function savedView(){setHead('Saved','Bookmark là câu bạn chủ động muốn giữ; tách riêng với SRS Review.');content().innerHTML='<div class="empty">Đang tải...</div>';try{const d=await api('/api/saved');const items=d.items;content().innerHTML=`<div class="section-head"><div><h2>${items.length} câu đã lưu</h2></div>${items.length?`<button class="btn primary small" id="savedRecallBtn">Active Recall</button>`:''}</div>${items.length?`<div class="sentence-list">${items.map((x,i)=>`<div class="sentence-row"><div class="sentence-index">${i+1}</div><button class="row-play" onclick="playUrl('${x.audio||''}')" ${x.audio?'':'disabled'}>▶</button><div class="sentence-text"><div class="en">${esc(x.en_us)} ${srsBadge(x)}</div><div class="vi">${esc(x.vi_vn||'')}</div></div><div class="row-side"><button class="save-btn on" onclick="removeSaved('${x.item_key}')">🔖</button><button class="icon-btn srs-menu-btn" onclick="openItemSrs('${x.item_key}')">⋯</button></div></div>`).join('')}</div>`:`<div class="empty">Chưa có câu đã lưu.</div>`}`;if(items.length)el('savedRecallBtn').onclick=()=>startRecallSession(dedupeItems(items),'saved_recall','Saved · Active Recall','saved')}catch(e){content().innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function removeSaved(key){try{await post('/api/bookmark',{item_key:key,saved:false});await refreshBoot();savedView()}catch(e){toast(e.message)}}
function playUrl(u){if(!u){toast('Không có audio');return}stopShadow(false);state.audioMode='single';player().src=u;player().play().catch(()=>toast('Không phát được audio'))}

function searchView(){setHead('Search','Tìm English hoặc tiếng Việt trong toàn bộ thư viện + câu tự thêm.');const filters=[['all','Tất cả'],['learn','Learn'],['vocabulary','Vocabulary'],['courses','Courses'],['my','My Islands'],['saved','Saved']];content().innerHTML=`<input id="q" class="searchbox" placeholder="Nhập từ hoặc câu..." autofocus aria-label="Tìm English hoặc tiếng Việt"><div class="search-filters" aria-label="Lọc kết quả">${filters.map(([key,label])=>`<button class="toggle-chip ${state.searchFilter===key?'on':''}" onclick="setSearchFilter('${key}')">${label}</button>`).join('')}</div><div id="sr" class="search-results"></div>`;const q=el('q');q.oninput=()=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>doSearch(q.value),220)}}
function setSearchFilter(filter){state.searchFilter=filter;document.querySelectorAll('.search-filters .toggle-chip').forEach((button,index)=>button.classList.toggle('on',['all','learn','vocabulary','courses','my','saved'][index]===filter));doSearch(el('q')?.value||'')}
function searchLocationLabel(location){return location?`${location.kind==='my'?'My Islands':esc(location.topic_name||location.kind)} → ${esc(location.collection_name)}`:'Không có vị trí nguồn'}
async function doSearch(q){const box=el('sr');if(q.trim().length<2){state.searchResults=[];box.innerHTML='';return}box.innerHTML='<div class="muted tiny">Đang tìm...</div>';try{const d=await api('/api/search?q='+encodeURIComponent(q)+'&filter='+encodeURIComponent(state.searchFilter));state.searchResults=d.items;box.innerHTML=d.items.length?d.items.map(x=>{const loc=x.primary_location;return `<div class="search-result"><button class="mini-play" onclick="playUrl('${x.audio||''}')" ${x.audio?'':'disabled'} aria-label="Phát audio">▶</button><div><div class="en">${esc(x.en_us)} ${srsBadge(x)}</div><div class="vi">${esc(x.vi_vn||'')}</div><div class="loc">${searchLocationLabel(loc)} ${x.other_location_count?`<button class="other-locations" onclick="openSearchLocations('${x.item_key}')">+${x.other_location_count} vị trí khác</button>`:''}</div></div><div class="result-actions"><button class="icon-btn" onclick="searchBookmark('${x.item_key}',${x.saved?'false':'true'})" aria-label="${x.saved?'Bỏ lưu':'Lưu câu'}">🔖</button><button class="icon-btn srs-menu-btn" onclick="openItemSrs('${x.item_key}')" aria-label="Quản lý ôn tập">⋯</button>${loc?`<button class="btn ghost small" onclick="openSearchLocation('${loc.collection_kind}',${loc.island_id},'${x.item_key}')">Mở</button>`:''}</div></div>`}).join(''):`<div class="empty">Không tìm thấy.</div>`}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function openSearchLocation(kind,id,itemKey){closeModal();openCollection(kind,id,'search',false,itemKey)}
function openSearchLocations(itemKey){const item=state.searchResults.find(x=>x.item_key===itemKey);if(!item)return;openModal(`<h2>Vị trí của câu</h2><p class="modal-copy">Cùng một canonical sentence có một lịch SRS chung ở mọi vị trí.</p><div class="source-picker">${(item.locations||[]).map(location=>`<button class="source-picker-row" onclick="openSearchLocation('${location.collection_kind}',${location.island_id},'${item.item_key}')"><span><b>${esc(location.collection_name)}</b><small>${esc(location.topic_name||location.kind)}</small></span><em>Mở →</em></button>`).join('')}</div>`)}
async function searchBookmark(key,target){try{await post('/api/bookmark',{item_key:key,saved:target});await refreshBoot();doSearch(el('q').value)}catch(e){toast(e.message)}}

function guideView(){setHead('How to Learn','Một quy trình rõ ràng thay vì chỉ có nội dung và nút Play.');content().innerHTML=`<div class="guide-wrap"><div class="guide-nav">${[['g1','Bắt đầu'],['g2','Language Island'],['g3','Learn'],['g4','Shadowing'],['g5','Active Recall'],['g6','FSRS'],['g7','Quản lý ôn tập'],['g8','Daily / Free'],['g9','My Islands'],['g10','Import XLSX & Audio'],['g11','Quản lý dữ liệu'],['g12','Gỡ cài đặt']].map(x=>`<button onclick="document.getElementById('${x[0]}').scrollIntoView({behavior:'smooth'})">${x[1]}</button>`).join('')}</div><div class="guide-content">
<div class="guide-section" id="g1"><h2>1. Bắt đầu thế nào?</h2><p>Chọn Learn, Vocabulary hoặc Courses → mở một bộ/Unit và học theo đúng thứ tự câu. Một vòng đầy đủ: <b>Learn → Shadowing → Active Recall → FSRS Review</b>.</p><div class="guide-callout">Không cần làm cả 4 bước trong một lần. Learn để hiểu; Shadowing để bắt nhịp; Recall để kiểm tra trí nhớ; Review để ôn đúng lúc.</div></div>
<div class="guide-section" id="g2"><h2>2. Language Island là gì?</h2><p>Island là một nhóm câu xoay quanh cùng tình huống/chủ đề. Học theo cụm giúp câu có ngữ cảnh và dễ tái sử dụng hơn học ngẫu nhiên.</p></div>
<div class="guide-section" id="g3"><h2>3. Learn — học theo danh sách</h2><ul><li>Đọc English + nghĩa Việt theo thứ tự.</li><li>Bấm audio ở bất kỳ câu nào hoặc bật Auto next.</li><li>Có thể ẩn tiếng Việt khi đã quen.</li><li>Learn/Listen <b>không</b> thay đổi lịch SRS.</li></ul></div>
<div class="guide-section" id="g4"><h2>4. Shadowing</h2><p>Nghe câu → nhại lại trong khoảng nghỉ → nghe/lặp lại → sang câu tiếp theo. Điều chỉnh tốc độ, số lần lặp và khoảng nghỉ cho vừa sức.</p><div class="guide-callout">Mục tiêu là bắt chước nhịp, nối âm và ngữ điệu; không cần ghi âm.</div></div>
<div class="guide-section" id="g5"><h2>5. Active Recall</h2><p>Đây là lúc dùng giao diện thẻ. Ưu tiên <b>VI → EN</b>: nhìn nghĩa Việt, tự nói English, rồi mới hiện đáp án. Có thêm Audio → EN và EN → Meaning.</p><p>Sau khi xem đáp án, chọn <b>Quên / Khó / Nhớ / Dễ</b>. Chỉ thao tác này mới cập nhật SRS.</p></div>
<div class="guide-section" id="g6"><h2>6. FSRS Spaced Repetition</h2><p>FSRS theo dõi trạng thái nhớ của từng câu và tính ngày ôn tiếp theo. Một câu chỉ có <b>một lịch SRS chung</b>, dù nó xuất hiện ở Island gốc, Vocabulary, Course hay My Island.</p><ul><li><b>Quên:</b> câu mới quay lại sau bước Learning; câu đã Review chuyển sang Relearning.</li><li><b>Khó:</b> khoảng ôn ngắn hơn.</li><li><b>Nhớ:</b> lịch bình thường.</li><li><b>Dễ:</b> khoảng ôn dài hơn.</li></ul><div class="guide-callout"><b>Desired Retention:</b> mặc định 90%. Tăng mức này sẽ ôn thường xuyên hơn. Người dùng bình thường nên giữ 90% và không cần chỉnh tham số FSRS nâng cao.</div></div>
<div class="guide-section" id="g7"><h2>7. Quản lý ôn tập</h2><p>Bấm nút <b>⋯</b> ở từng câu hoặc nút <b>Ôn tập</b> ở đầu một bộ để quản lý lịch.</p><ul><li><b>Ôn lại ngay:</b> đưa câu đã có SRS đến hạn ngay, nhưng giữ nguyên Stability, Difficulty và lịch sử.</li><li><b>Reset về Chưa học:</b> xóa trạng thái/lịch FSRS hiện tại để câu trở lại New. Lịch sử review vẫn được giữ.</li><li><b>Tạm dừng ôn tập:</b> ẩn câu khỏi Daily Study. Khi tiếp tục, lịch FSRS cũ vẫn còn; nếu ngày hẹn đã qua thì câu sẽ đến hạn.</li><li><b>Thông tin SRS:</b> xem trạng thái, ngày ôn tiếp theo, Stability, Difficulty, lượt ôn và số lần quên.</li></ul><div class="guide-callout">Khi thao tác cả bộ, app chỉ xử lý mỗi canonical sentence một lần. Nếu câu đó còn xuất hiện ở bộ khác, trạng thái SRS chung của câu cũng thay đổi.</div></div>
<div class="guide-section" id="g8"><h2>8. Daily Study và Free Study</h2><p><b>Daily Study:</b> ôn tất cả câu đến hạn trước, sau đó học số câu mới theo giới hạn ngày. Câu đang tạm dừng được bỏ qua. Learning/Relearning chỉ hiện lại khi đúng thời điểm đã hẹn.</p><p><b>Free Study:</b> học thêm 10/20 câu hoặc học hết Island. Việc đọc/nghe tự do không phá lịch SRS; chỉ rating trong Active Recall mới làm thay đổi lịch.</p></div>
<div class="guide-section" id="g9"><h2>9. My Islands</h2><p>Tạo Island riêng, tìm câu trong toàn bộ thư viện để thêm, kéo đổi thứ tự, hoặc tự thêm câu mới với English + Vietnamese + file audio riêng. Xóa câu khỏi My Island không xóa câu gốc hay lịch SRS.</p></div>
<div class="guide-section" id="g10"><h2>10. Import XLSX & Bulk Audio</h2><p>Dùng XLSX để thêm hàng trăm hoặc hàng nghìn câu vào một My Island. Mỗi dòng gồm <b>Audio Key · English · Vietnamese · Audio file · Note</b>.</p><div class="guide-callout"><b>Cách nhanh:</b> đặt Audio Key T001, T002... rồi đặt tên MP3 tương ứng T001.mp3, T002.mp3... Sau khi import XLSX, nén toàn bộ MP3 thành một ZIP (khuyên dùng) hoặc chọn cả folder rồi bấm <b>Bulk Audio</b>. App sẽ tự ghép, không cần mở từng câu.</div><p>Nếu chưa có audio, cứ import câu trước. Khi có audio sau, dùng Bulk Audio để bổ sung. Audio Key được giữ ổn định dù bạn đổi thứ tự câu.</p><a class="btn secondary small no-underline" href="/template/my-island.xlsx">↓ Tải file XLSX mẫu</a></div>
<div class="guide-section" id="g11"><h2>11. Quản lý dữ liệu</h2><ul><li><b>Reset tiến độ học:</b> học lại từ đầu nhưng vẫn giữ My Islands, Saved, câu/audio cá nhân và Settings.</li><li><b>Xóa toàn bộ dữ liệu người dùng:</b> đưa app về trạng thái như mới dùng lần đầu.</li><li><b>Sao lưu dữ liệu:</b> lưu progress, review history, Saved, My Islands, Settings và user audio vào một file ZIP.</li><li><b>Khôi phục dữ liệu:</b> thay thế toàn bộ dữ liệu hiện tại bằng dữ liệu trong file backup.</li></ul><div class="guide-callout">Nên sao lưu trước khi chuyển máy, xóa dữ liệu hoặc gỡ ứng dụng hoàn toàn.</div></div>
<div class="guide-section" id="g12"><h2>12. Gỡ cài đặt</h2><h3>Gỡ ứng dụng nhưng giữ dữ liệu học</h3><ol><li>Đóng app hoàn toàn.</li><li>Xóa thư mục English Learning App đã giải nén.</li><li>Không xóa <b>%LOCALAPPDATA%\EnglishLocal</b>.</li><li>Khi dùng lại app, dữ liệu học cũ vẫn còn.</li></ol><h3>Xóa sạch ứng dụng hoàn toàn</h3><ol><li>Nếu cần, dùng <b>Sao lưu dữ liệu</b> trước.</li><li>Đóng app hoàn toàn.</li><li>Xóa thư mục chương trình English Learning App.</li><li>Xóa <b>%LOCALAPPDATA%\EnglishLocal</b>.</li><li>Xóa shortcut nếu bạn tự tạo.</li></ol><div class="guide-callout danger-callout"><b>Cảnh báo:</b> Xóa %LOCALAPPDATA%\EnglishLocal sẽ xóa vĩnh viễn tiến độ học, lịch sử ôn tập, Saved, My Islands, câu/audio tự thêm và Settings nếu chưa sao lưu.</div><p>Ứng dụng không tự gỡ cài đặt hoặc tự xóa file chương trình.</p></div>
</div></div>`}

function dataSettingsCard(){return `<div class="setting-card data-card" id="dataSettings"><div class="data-card-head"><div><h3>Dữ liệu</h3><p>Quản lý tiến độ, My Islands, Saved, Settings và audio cá nhân trong <b>%LOCALAPPDATA%\\EnglishLocal</b>.</p></div><button class="btn ghost small" onclick="openUserDataFolder()">Mở thư mục dữ liệu</button></div><div class="data-action-list"><div class="data-action"><div><b>Reset tiến độ học</b><small>Xóa tiến độ, lịch FSRS và lịch sử ôn tập; giữ nội dung cá nhân và thiết lập.</small></div><button class="btn danger small" onclick="openResetProgressModal()">Reset tiến độ</button></div><div class="data-action"><div><b>Sao lưu dữ liệu người dùng</b><small>Tạo ZIP nhất quán gồm database, manifest, checksum và toàn bộ user audio.</small></div><button class="btn secondary small" onclick="backupUserData()">Sao lưu dữ liệu</button></div><div class="data-action"><div><b>Khôi phục dữ liệu người dùng</b><small>Thay thế dữ liệu hiện tại bằng một file backup hợp lệ.</small></div><button class="btn secondary small" onclick="el('restoreBackupInput').click()">Khôi phục dữ liệu</button><input id="restoreBackupInput" class="hidden" type="file" accept=".zip,application/zip" onchange="prepareRestoreBackup(this.files?.[0])"></div><div class="data-action destructive"><div><b>Xóa toàn bộ dữ liệu người dùng</b><small>Đưa ứng dụng về trạng thái như mới dùng lần đầu. Thao tác không thể hoàn tác.</small></div><button class="btn danger small" onclick="openDeleteAllModal()">Xóa toàn bộ dữ liệu</button></div></div><div class="data-help-links"><button class="link-btn" onclick="openGuideSection('g11')">Hướng dẫn quản lý dữ liệu</button><button class="link-btn" onclick="openGuideSection('g12')">Hướng dẫn gỡ cài đặt</button></div></div><div class="setting-card"><h3>About</h3><p>English Learning App chạy local/offline và không yêu cầu tài khoản.</p><div class="info-strip"><b>Phiên bản ${esc(state.boot.appVersion)}</b><br><span class="tiny muted">User DB schema ${state.boot.userDbSchemaVersion} · Backup format ${state.boot.backupFormatVersion}</span></div></div>`}

function settingsView(){const s=state.boot.settings;setHead('Settings','Các thiết lập có ảnh hưởng trực tiếp tới kế hoạch học.');content().innerHTML=`<div class="settings-grid"><div class="setting-card"><h3>Daily Study</h3><p>Giới hạn câu mới mỗi ngày. Review đến hạn không bị giới hạn.</p><div class="form-row"><label>Câu mới / ngày</label><select id="setNew" class="field" onchange="saveSetting('new_per_day',this.value)">${[['10','10'],['20','20'],['30','30'],['50','50'],['-1','Không giới hạn']].map(([v,t])=>`<option value="${v}" ${String(s.new_per_day)===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="setting-card"><h3>FSRS</h3><p>Desired retention cao hơn = ôn thường xuyên hơn. 90% là mức mặc định cân bằng.</p><div class="form-row"><label>Desired retention <button class="help-inline" title="Mục tiêu xác suất nhớ khi câu đến hạn" onclick="render('guide');setTimeout(()=>document.getElementById('g6')?.scrollIntoView(),100)">?</button></label><select class="field" onchange="saveSetting('desired_retention',this.value)">${[['0.85','85%'],['0.90','90%'],['0.93','93%'],['0.95','95%']].map(([v,t])=>`<option value="${v}" ${Number(s.desired_retention)===Number(v)?'selected':''}>${t}</option>`).join('')}</select></div><label class="check-line"><input type="checkbox" ${String(s.reschedule_on_retention_change||'0')==='1'?'checked':''} onchange="saveSetting('reschedule_on_retention_change',this.checked?'1':'0')"><span><b>Reschedule existing cards</b><small>OFF mặc định. Khi bật, đổi Desired Retention sẽ cập nhật ngay due date của các câu đang Review.</small></span></label><small class="tiny muted">Scheduler: FSRS-6 core · deterministic (fuzzing off). Không chỉnh trực tiếp FSRS parameters.</small></div><div class="setting-card"><h3>Active Recall mặc định</h3><p>Chế độ mở sẵn khi vào Recall.</p><select class="field" onchange="saveSetting('recall_mode',this.value)"><option value="vi_en" ${s.recall_mode==='vi_en'?'selected':''}>VI → EN</option><option value="audio_en" ${s.recall_mode==='audio_en'?'selected':''}>Audio → EN</option><option value="en_meaning" ${s.recall_mode==='en_meaning'?'selected':''}>EN → Meaning</option></select></div><div class="setting-card"><h3>Auto next</h3><p>Khoảng nghỉ sau khi audio kết thúc trước khi phát câu kế tiếp.</p><div class="form-row"><label>Khoảng nghỉ</label><select class="field" onchange="saveSetting('list_auto_delay',this.value)">${[0,.5,1,2,3,5].map(v=>`<option value="${v}" ${Number(s.list_auto_delay??1)===v?'selected':''}>${v}s</option>`).join('')}</select></div></div><div class="setting-card"><h3>Shadowing mặc định</h3><p>Áp dụng cho các Island khi mở Shadowing.</p><div class="form-row"><label>Speed</label><select class="field" onchange="saveSetting('shadow_speed',this.value)">${[.75,.9,1,1.1,1.25].map(v=>`<option value="${v}" ${Number(s.shadow_speed)===v?'selected':''}>${v}×</option>`).join('')}</select></div><div class="form-row"><label>Lặp</label><select class="field" onchange="saveSetting('shadow_repeat',this.value)">${[1,2,3,5].map(v=>`<option value="${v}" ${Number(s.shadow_repeat)===v?'selected':''}>${v}×</option>`).join('')}</select></div><div class="form-row"><label>Khoảng nghỉ</label><select class="field" onchange="saveSetting('shadow_pause',this.value)">${[.5,1,2,3,5].map(v=>`<option value="${v}" ${Number(s.shadow_pause)===v?'selected':''}>${v}s</option>`).join('')}</select></div></div>${dataSettingsCard()}<div class="setting-card"><h3>Offline</h3><p>Audio của bộ chính và 4000 Essential English Words được lưu ngay trong app; Course mới có thể bổ sung audio theo ZIP. Không cần login, backend hay Internet để học.</p><div class="flow"><span>EN-US</span><i>·</i><span>VI</span><i>·</i><span>Charon</span></div></div></div>`}
async function saveSetting(key,value){try{const r=await post('/api/setting',{key,value});await refreshBoot();if(key.startsWith('shadow_')){state.shadow.speed=Number(state.boot.settings.shadow_speed);state.shadow.repeat=Number(state.boot.settings.shadow_repeat);state.shadow.pause=Number(state.boot.settings.shadow_pause)}if(key==='desired_retention'&&Number(r.rescheduled||0)>0)toast(`Đã lưu · reschedule ${r.rescheduled} câu Review`);else toast('Đã lưu thiết lập')}catch(e){toast(e.message)}}

function openGuideSection(id){render('guide');setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),100)}

function openResetProgressModal(){openModal(`<h2>Reset tiến độ học?</h2><p class="modal-copy">Thao tác này sẽ xóa toàn bộ tiến độ học và lịch sử ôn tập. My Islands, Saved, câu/audio cá nhân và Settings vẫn được giữ.</p><div class="form-actions"><button id="resetProgressBtn" class="btn danger" onclick="confirmResetProgress()">Reset tiến độ học</button><button class="btn ghost" onclick="closeModal()">Hủy</button></div>`)}

async function confirmResetProgress(){const button=el('resetProgressBtn');if(button){button.disabled=true;button.textContent='Đang reset...'}try{await post('/api/data/reset-progress',{});closeModal();await refreshBoot();settingsView();toast('Đã reset toàn bộ tiến độ học')}catch(e){if(button){button.disabled=false;button.textContent='Reset tiến độ học'}toast(e.message)}}

function openDeleteAllModal(){openModal(`<h2>Xóa toàn bộ dữ liệu người dùng?</h2><p class="modal-copy">Tiến độ, lịch sử ôn tập, Saved, My Islands, câu/audio tự thêm và toàn bộ Settings sẽ bị xóa. Nội dung và audio đi kèm ứng dụng không bị ảnh hưởng.</p><div class="danger-note">Thao tác này không thể hoàn tác. Hãy sao lưu trước nếu bạn có thể cần dữ liệu hiện tại.</div><div class="form-actions"><button class="btn danger" onclick="openDeleteAllFinalStep()">Tiếp tục</button><button class="btn ghost" onclick="closeModal()">Hủy</button></div>`)}

function openDeleteAllFinalStep(){openModal(`<h2>Xác nhận lần cuối</h2><p class="modal-copy">Nhập <b>XÓA DỮ LIỆU</b> để xác nhận đưa ứng dụng về trạng thái như mới.</p><div class="form-row"><label for="deleteAllPhrase">Cụm từ xác nhận</label><input id="deleteAllPhrase" class="field" autocomplete="off" autofocus oninput="el('confirmDeleteAllBtn').disabled=this.value.trim()!=='XÓA DỮ LIỆU'"></div><div class="form-actions"><button id="confirmDeleteAllBtn" class="btn danger" disabled onclick="confirmDeleteAll()">Xóa vĩnh viễn</button><button class="btn ghost" onclick="closeModal()">Hủy</button></div>`)}

async function confirmDeleteAll(){const button=el('confirmDeleteAllBtn');if(button){button.disabled=true;button.textContent='Đang xóa...'}try{await post('/api/data/delete-all',{});el('modalBody').innerHTML='<h2>Đã xóa dữ liệu</h2><p class="modal-copy">Ứng dụng đang tải lại profile mặc định...</p>';setTimeout(()=>location.reload(),250)}catch(e){if(button){button.disabled=false;button.textContent='Xóa vĩnh viễn'}toast(e.message)}}

function suggestedBackupName(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `EnglishLearningApp-user-data-${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}.zip`}

async function backupResponseError(response){try{const d=await response.json();return d.error||'Không thể tạo backup'}catch{return 'Không thể tạo backup'}}

async function backupUserData(){const filename=suggestedBackupName();if(window.pywebview?.api?.save_user_backup){try{toast('Đang mở hộp thoại lưu...');const result=await window.pywebview.api.save_user_backup(filename);if(result?.cancelled)return;if(!result?.ok)throw new Error(result?.error||'Không thể tạo backup');toast(`Đã sao lưu: ${result.filename}`);return}catch(e){toast(e.message);return}}let handle=null;if(window.showSaveFilePicker){try{handle=await window.showSaveFilePicker({suggestedName:filename,types:[{description:'English Learning App backup',accept:{'application/zip':['.zip']}}]})}catch(e){if(e?.name==='AbortError')return;handle=null}}try{toast('Đang tạo snapshot dữ liệu...');const response=await fetch('/api/data/backup',{cache:'no-store'});if(!response.ok)throw new Error(await backupResponseError(response));if(handle){const writable=await handle.createWritable();if(response.body?.pipeTo)await response.body.pipeTo(writable);else{await writable.write(await response.blob());await writable.close()}}else{const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}toast('Đã sao lưu dữ liệu')}catch(e){toast(e.message)}}

function prepareRestoreBackup(file){if(!file)return;state.pendingRestoreFile=file;openModal(`<h2>Khôi phục dữ liệu?</h2><p class="modal-copy">Khôi phục sẽ thay thế toàn bộ dữ liệu người dùng hiện tại bằng bản sao lưu.</p><div class="backup-file-summary"><b>${esc(file.name)}</b><small>${formatNum(file.size)} bytes</small></div><p class="tiny muted">Ứng dụng kiểm tra ZIP, manifest, checksum, schema và integrity trong staging, tạo safety snapshot, sau đó tự đóng. Lần mở app tiếp theo sẽ thay dữ liệu trước khi database/server được khởi động.</p><div class="form-actions"><button id="restoreDataBtn" class="btn danger" onclick="confirmRestoreBackup()">Khôi phục dữ liệu</button><button class="btn ghost" onclick="cancelRestoreBackup()">Hủy</button></div>`)}

function cancelRestoreBackup(){state.pendingRestoreFile=null;closeModal();const input=el('restoreBackupInput');if(input)input.value=''}

async function confirmRestoreBackup(){const file=state.pendingRestoreFile;if(!file)return;const button=el('restoreDataBtn');if(button){button.disabled=true;button.textContent='Đang kiểm tra backup...'}try{await api('/api/data/restore',{method:'POST',headers:{'Content-Type':'application/zip'},body:file});state.pendingRestoreFile=null;el('modalBody').innerHTML='<h2>Đã chuẩn bị khôi phục</h2><p class="modal-copy">Dữ liệu đã được chuẩn bị an toàn. Ứng dụng sẽ đóng. Hãy mở lại English Learning App để hoàn tất khôi phục.</p>'}catch(e){cancelRestoreBackup();toast(e.message)}}

async function openUserDataFolder(){try{await post('/api/data/open-folder',{});toast('Đã mở thư mục dữ liệu')}catch(e){toast(e.message)}}

// Keyboard: Space controls list audio / recall reveal. Escape closes modal.
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!el('modal').classList.contains('hidden'))return closeModal();if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.code==='Space'){if(state.view==='recall'){e.preventDefault();if(!state.recall.revealed)revealRecall();else playRecallAudio()}else if(state.view==='collection'&&state.collectionTab==='list'){e.preventDefault();if(state.listAudioIndex<0)playCollectionAudio(0);else togglePlayerPlay()}}});

bootstrap().catch(e=>{setHead('Lỗi khởi động');content().innerHTML=`<div class="empty">${esc(e.message)}</div>`});
